diff --git a/app/api/profile/[userId]/gallery/route.ts b/app/api/profile/[userId]/gallery/route.ts
new file mode 100644
index 0000000..a68823d
--- /dev/null
+++ b/app/api/profile/[userId]/gallery/route.ts
@@ -0,0 +1,64 @@
+import { NextRequest, NextResponse } from 'next/server';
+import { z } from 'zod';
+
+import { infiniteQueryFunction } from '@/app/[locale]/(main)/profile/[id]/[type]/_utils/shared';
+import type { Category, WorkType } from '@/app/[locale]/(main)/profile/[id]/[type]/_components/types';
+import createLogger from '@/lib/logger';
+
+const logger = createLogger('api-profile-gallery');
+
+const schema = z.object({
+  type: z.enum(['image', 'video', 'webtoon', 'loras']),
+  category: z.enum(['showcase', 'collection', 'all']),
+  sort: z.enum(['created', 'popular']).optional(),
+  search: z.string().optional(),
+  cursor: z.string().optional()
+});
+
+export async function GET(
+  request: NextRequest,
+  { params }: { params: Promise<{ userId: string }> }
+) {
+  try {
+    const { userId } = await params;
+    const searchParams = request.nextUrl.searchParams;
+    const queryParams = Object.fromEntries(searchParams.entries());
+
+    const validated = schema.safeParse({
+      ...queryParams,
+      type: queryParams.type ?? 'image',
+      category: queryParams.category ?? 'showcase',
+      sort: queryParams.sort ?? 'created',
+      search: queryParams.search ?? ''
+    });
+
+    if (!validated.success) {
+      return NextResponse.json(
+        { error: 'Invalid query parameters', details: validated.error.flatten() },
+        { status: 400 }
+      );
+    }
+
+    const { type, category, sort, search, cursor } = validated.data;
+
+    const result = await infiniteQueryFunction({
+      viewUserId: userId,
+      type: type as WorkType,
+      category: category as Category,
+      cursor,
+      sort: sort ?? 'created',
+      searchTerm: search ?? ''
+    });
+
+    return NextResponse.json(result);
+  } catch (error) {
+    logger.error(
+      'Error fetching profile gallery',
+      error instanceof Error ? error : { cause: String(error) }
+    );
+    return NextResponse.json(
+      { error: 'Internal server error' },
+      { status: 500 }
+    );
+  }
+}
